begin.example:
kcds.world.PropPlacer.begin(player, {
  model: 'beer_barrel',
  rules: { maxDistance: 6, maxSlope: 30 },
  spawn: { physics: 'static' },
});

kcds.core.Events.on('propPlaceConfirm', (placer, session, placement) => {
  return placement.surface !== 'water';
});

begin.exampleCs:
PropPlacer.Begin(player, new { model = "beer_barrel", rules = new { maxDistance = 6, maxSlope = 30 }, spawn = new { physics = "static" } });

Events.On("propPlaceConfirm", object? (Player placer, JsValue session, JsValue placement) =>
{
    return placement["surface"].AsString() != "water";
});

isActive.example:
// client
const { PropPlacer } = kcds.world;

if (PropPlacer.isActive()) {
  PropPlacer.end();
}

getPose.example:
// client
const pose = kcds.world.PropPlacer.getPose();
if (pose?.onSurface) {
  console.log(`aimed at ${pose.position}, ${pose.distance.toFixed(1)} m away`);
}

getPose.exampleCs:
// client
var pose = PropPlacer.GetPose();
if (pose["onSurface"])
{
    Log.Info($"aimed at {pose["position"]}, {pose["distance"].AsNumber().ToString("F1")} m away");
}

on.example:
// client
const { PropPlacer } = kcds.world;

PropPlacer.on('confirm', (pose) => {
  kcds.core.Events.toServer('buildTent', { position: pose.position, rotation: pose.rotation });
});
PropPlacer.on('rejected', () => kcds.ui.Hud.showNotification('You cannot build there.'));

on.exampleCs:
// client

PropPlacer.On("confirm", (JsValue pose) =>
{
    Events.ToServer("buildTent", new { position = pose["position"], rotation = pose["rotation"] });
});
PropPlacer.On("rejected", () => Hud.ShowNotification("You cannot build there."));

begin.example:
// client
const { PropPlacer } = kcds.world;

PropPlacer.begin({
  model: 'objects/manmade/structures/living/tents/canopy_forest_a.cgf',
  rules: { maxSlope: 20, maxDistance: 8 },
});
PropPlacer.on('confirm', (pose) => kcds.core.Events.toServer('pitchTent', pose.position));

begin.exampleCs:
// client

PropPlacer.Begin(new { model = "objects/manmade/structures/living/tents/canopy_forest_a.cgf", rules = new { maxSlope = 20, maxDistance = 8 } });
PropPlacer.On("confirm", (JsValue pose) => Events.ToServer("pitchTent", pose["position"]));
